import React from 'react';
import { Container } from './Card.styles';
import { CardTypes } from './Card.types';

const Card = React.forwardRef(
  (
    { elevated, border, children, css, ...props }: Omit<CardTypes, 'as'>,
    forwardedRef: React.ForwardedRef<HTMLDivElement>
  ): JSX.Element => (
    <Container elevated={elevated} border={border} css={css} ref={forwardedRef} {...props}>
      {children}
    </Container>
  )
);

export default Card;
